INSERT INTO lesson_blocks (id, lesson_id, sort_order, block_type, text_content) VALUES ('cf040000-0000-4000-8000-000000000001', 'cf030000-0000-4000-8000-000000000001', 1, 'TEXT', 'Khi đọc một đoạn ngắn, hãy hỏi: đoạn này viết về cái gì? Câu đầu và tiêu đề thường cho biết chủ đề. Các câu sau thêm chi tiết: ai, khi nào, ở đâu, bao nhiêu. Đừng dừng lại ở từ mới: đọc hết câu, rồi đoán nghĩa từ các từ xung quanh. Trả lời câu hỏi chủ đề trước, sau đó mới tìm chi tiết.');
