INSERT INTO lesson_blocks (id, lesson_id, sort_order, block_type, text_content) VALUES ('cf040000-0000-4000-8000-000000000004', 'cf030000-0000-4000-8000-000000000002', 1, 'TEXT', 'Trong Part 1, người nói thường đánh vần tên: "Okafor, O, K, A, F, O, R". Hãy ôn cách đọc 26 chữ cái, nhất là các cặp dễ nhầm: A và E, G và J, I và Y, M và N. Viết từng chữ cái ngay khi nghe, đừng đợi nghe hết tên. Nghe "double L" nghĩa là hai chữ L liền nhau. Cuối cùng, kiểm tra lại chính tả và viết hoa chữ cái đầu của tên.');
