INSERT INTO lesson_blocks (id, lesson_id, sort_order, block_type, text_content) VALUES ('cf040000-0000-4000-8000-000000000007', 'cf030000-0000-4000-8000-000000000003', 1, 'TEXT', 'Chi tiết quen thuộc gồm ngày tháng, giờ, giá tiền và số lượng. Trước khi nghe, nhìn câu hỏi và đoán loại thông tin: "How many nights?" cần một con số, "How much?" cần giá tiền. Ngày tháng thường đọc là "the twelfth of June". Giá tiền có hai phần: "eighteen pounds fifty" là 18.50. Ghi con số bằng chữ số để viết nhanh hơn.');
