INSERT INTO lesson_blocks (id, lesson_id, sort_order, block_type, text_content) VALUES ('cf040000-0000-4000-8000-000000000010', 'cf030000-0000-4000-8000-000000000004', 1, 'TEXT', 'Muốn viết được câu, bạn cần một vốn từ thông dụng: gia đình (parents, brother), công việc (office, manager), mua sắm (price, cheap, expensive), đi lại (bus, ticket, station). Học từ theo nhóm chủ đề và luôn học kèm một câu ví dụ. Chú ý từ hay dùng sai: "borrow" là mượn, "lend" là cho mượn; "fun" là vui, "funny" là buồn cười.');
