INSERT INTO lesson_blocks (id, lesson_id, sort_order, block_type, text_content) VALUES ('cf040000-0000-4000-8000-000000000012', 'cf030000-0000-4000-8000-000000000005', 1, 'TEXT', 'Câu tiếng Anh cơ bản có trật tự: chủ ngữ + động từ + tân ngữ hoặc bổ ngữ. "My sister works in a hospital." Mỗi câu cần một động từ chia đúng: chủ ngữ số ít ở hiện tại đơn thêm -s (she works). Tính từ đứng sau "be" (The room is small) hoặc trước danh từ (a small room). Không bỏ "be": viết "He is tired", không viết "He tired".');
