INSERT INTO lessons (id, topic_id, code, title, sort_order, status, estimated_minutes) VALUES ('cf030000-0000-4000-8000-000000000006', (SELECT id FROM topics WHERE code = 'FOUNDATION_WRITING'), 'F-W3', 'Viết đoạn văn đơn giản', 3, 'PUBLISHED', 10);
INSERT INTO lesson_knowledge_points (lesson_id, knowledge_point_id) VALUES ('cf030000-0000-4000-8000-000000000006', (SELECT id FROM knowledge_points WHERE code = 'W55_SIMPLE_PARAGRAPH'));
INSERT INTO lesson_blocks (id, lesson_id, sort_order, block_type, text_content) VALUES ('cf040000-0000-4000-8000-000000000014', 'cf030000-0000-4000-8000-000000000006', 1, 'TEXT', 'Một đoạn văn đơn giản có ba phần. Câu chủ đề nói đoạn văn viết về gì: "I like living in my town." Hai hoặc ba câu hỗ trợ đưa lý do hoặc ví dụ, nối bằng "and", "but", "because". Câu kết nhắc lại ý chính bằng cách khác. Mọi câu phải nói về cùng một ý; câu lạc đề làm đoạn văn rời rạc.');
INSERT INTO lesson_block_knowledge_points (block_id, knowledge_point_id) VALUES ('cf040000-0000-4000-8000-000000000014', (SELECT id FROM knowledge_points WHERE code = 'W55_SIMPLE_PARAGRAPH'));
